import React, { useState, useEffect } from 'react';
import { getAllRestaurants, getAllUsers } from '../../services/api'; // assume you have this API
import { useNavigate } from 'react-router-dom';

const RestaurantList = () => {
  const [restaurants, setRestaurants] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState('restaurant'); // 👈 toggle mode
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 10000);
    return () => clearInterval(interval);
  }, [viewMode]);

  const loadData = async () => {
    try {
      if (viewMode === 'restaurant') {
        const res = await getAllRestaurants();
        setRestaurants(res.data);
      } else {
        const res = await getAllUsers();
        setUsers(res.data);
      }
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  // ✅ Filtering logic (based on active view)
  const filteredRestaurants = restaurants.filter((restaurant) =>
    restaurant.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    restaurant.cuisine_type?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    restaurant.address.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredUsers = users.filter((user) =>
    user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.role?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const activeList = viewMode === 'restaurant' ? filteredRestaurants : filteredUsers;

  if (loading) return (
    <div style={styles.loadingContainer}>
      <div style={styles.spinner}></div>
      <p style={styles.loadingText}>Loading {viewMode}s...</p>
    </div>
  );

  return (
    <div style={styles.container}>
      {/* 🎛️ Toggle View */}
      <div style={{ textAlign: 'center', marginTop: '1rem' }}>
        <button 
          style={{ ...styles.toggleBtn, background: viewMode === 'restaurant' ? '#7B542F' : '#ccc' }}
          onClick={() => setViewMode('restaurant')}
        >
          Restaurants
        </button>
        <button 
          style={{ ...styles.toggleBtn, background: viewMode === 'user' ? '#7B542F' : '#ccc' }}
          onClick={() => setViewMode('user')}
        >
          Customers
        </button>
      </div>

      {/* 🔍 Search */}
      <div style={styles.hero}>
        <div style={styles.searchContainer}>
          <span style={styles.searchIcon}>🔍</span>
          <input
            type="text"
            placeholder={`Search by ${viewMode === 'restaurant' ? 'restaurant name, cuisine, or location' : 'user name, email, or role'}...`}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={styles.searchInput}
          />
          {searchTerm && (
            <button onClick={() => setSearchTerm('')} style={styles.clearBtn}>✕</button>
          )}
        </div>

        <div style={styles.statsBar}>
          <div style={styles.stat}>
            <span style={styles.statNumber}>{activeList.length}</span>
            <span style={styles.statLabel}>
              {viewMode === 'restaurant' ? 'Restaurants' : 'Customers'}
            </span>
          </div>
        </div>
      </div>

      {/* 🧩 List */}
      {activeList.length === 0 ? (
        <div style={styles.emptyState}>
          <h2 style={styles.emptyTitle}>No {viewMode}s found</h2>
          <p style={styles.emptyText}>Try searching for something else!</p>
        </div>
      ) : (
        <div style={styles.grid}>
          {viewMode === 'restaurant' ? (
            filteredRestaurants.map((restaurant) => (
              <div
                key={restaurant.id}
                style={styles.card}
                onClick={() => navigate(`/restaurant/${restaurant.id}`)}
              >
                <img
                  src={restaurant.image_url || 'https://via.placeholder.com/400x250?text=Delicious+Food'}
                  alt={restaurant.name}
                  style={styles.image}
                />
                <div style={styles.cardContent}>
                  <h3>{restaurant.name}</h3>
                  <p>{restaurant.cuisine_type}</p>
                  <p>{restaurant.address}</p>
                </div>
              </div>
            ))
          ) : (
            filteredUsers.map((user) => (
              <div key={user.id} style={styles.card}>
                <h3>{user.name}</h3>
                <p>{user.email}</p>
                <p>{user.role}</p>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

const styles = {
  // keep your existing styles...
  toggleBtn: {
    padding: '0.7rem 1.5rem',
    margin: '0.5rem',
    border: 'none',
    borderRadius: '20px',
    color: 'white',
    fontWeight: '600',
    cursor: 'pointer',
    transition: '0.3s',
  },
};

export default RestaurantList;
